from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
def read(p): return (ROOT/p).read_text()
def load(p): return json.loads(read(p))
def test_m274_release_and_contract():
 d=load('data/release_identity.json'); assert d['milestone'] in {'M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and d['client_version'] in {'0.274.0','0.275.0','0.276.0','0.277.0','0.278.0','0.279.0','0.280.0','0.281.0','0.282.0','0.283.0','0.284.0','0.285.0','0.286.0','0.287.0','0.288.0','0.289.0','0.290.0','0.291.0','0.292.0','0.293.0','0.294.0','0.295.0','0.296.0','0.297.0','0.298.0','0.299.0','0.300.0','0.301.0'} and d['build_number'] in {274,275,276,277,278,279,280,281,282,283,284,285,286,287,288,289,290,291,292,293,294,295,296,297,298,299,300,301} and d['content_config_version'] in {'M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and d['master_concept']=='V3.8'
 c=load('data/m274_authoritative_kill_credit_reward_persistence_contract.json'); assert c['contract']=='authoritative_kill_credit_loot_reward_eligibility_encounter_persistence_foundation'; assert c['genre_ux_references']==['Seafight','Battle of Sea']; assert all(x in c['authority']['server_owns'] for x in ['contribution_ledger','kill_credit','reward_eligibility','loot_drop_authorization','encounter_persistence','reconnect_recovery'])
def test_m274_runtime_fail_closed_and_revision_guarded():
 s=read('scripts/online/m274_authoritative_kill_credit_reward_persistence_runtime.gd')
 for t in ['bind_encounter_orchestration','ingest_server_eligibility_snapshot','ingest_server_reward_event','eligibility_revision','persistence_revision','settlement_sequence','contribution_state','kill_credit_state','eligibility_state','loot_authorization','reward_authorization','persistence_state','invalidate_from_world_resync']: assert t in s
 for t in ['can_client_assign_kill_credit() -> bool: return false','can_client_set_contribution() -> bool: return false','can_client_mark_reward_eligible() -> bool: return false','can_client_roll_loot() -> bool: return false','can_client_authorize_loot_drop() -> bool: return false','can_client_grant_reward() -> bool: return false','can_client_restore_encounter_credit() -> bool: return false','can_client_confirm_settlement() -> bool: return false','can_client_transfer_test_reward_to_global() -> bool: return false']: assert t in s
 assert 'er <= eligibility_revision' in s and 'seq <= settlement_sequence' in s and '"can_settle":false' in s
def test_m274_bootstrap_deck_admin_dependencies():
 b=read('scripts/core/game_bootstrap.gd'); deck=read('scripts/ui/command_deck.gd'); assert 'M274AuthoritativeKillCreditRewardPersistenceRuntime.new()' in b and 'AuthoritativeKillCreditRewardPersistenceReadiness' in b; assert 'KILL CREDIT · LOOT · REWARD ELIGIBILITY · PERSISTENCE' in deck and 'M274AuthoritativeKillCreditRewardPersistenceCatalog.settlement()' in deck
 a=load('data/admin_content_type_registry.json'); assert a['milestone'] in {'M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and all(x in a['content_types'] for x in ['kill_credit_policy_definition','contribution_eligibility_policy_definition','loot_reward_authorization_policy_definition','encounter_persistence_recovery_policy_definition'])
 c=load('data/m274_authoritative_kill_credit_reward_persistence_contract.json'); assert c['dependencies']['encounter'].startswith('M273') and c['dependencies']['combat'].startswith('M269/M270') and c['dependencies']['settlement'].startswith('M266')
def test_m274_convergence_and_unset_tuning():
 m=load('data/m239_master_convergence_matrix.json'); assert m['milestone'] in {'M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'}; row={x['domain']:x for x in m['domains']}['authoritative_kill_credit_loot_reward_eligibility_encounter_persistence']; assert row['status']=='PARTIAL' and 'm274_fix' in row and any(x.startswith('production authoritative contribution ledger') for x in row['remaining'])
 c=load('data/m274_authoritative_kill_credit_reward_persistence_contract.json'); assert all(x in c['unset_until_measured'] for x in ['minimum_contribution_thresholds','contribution_weights','drop_probabilities','reward_values','disconnect_grace','anti_farm_windows'])
